INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (9951, 'Affordances trong thiết kế UX', 'affordances-trong-thiet-ke-ux', '
<p>Nhiều nhà thiết kế cố gắng tạo ra các sản phẩm dễ điều hướng đến mức người dùng của họ có thể lướt qua chúng ngay từ cái nhìn đầu tiên. Để thiết kế thứ gì đó với mức độ trực giác này, các nhà thiết kế bắt buộc phải hiểu Affordances—chúng là gì và cách sử dụng chúng.</p>



<p>Affordances có ở xung quanh chúng ta nhưng việc làm quen với cách chúng tác động đến thiết kế UX là rất quan trọng để thiết kế các sản phẩm chất lượng cao, thân thiện với người dùng.</p>



<p>Để cung cấp cho bạn bảng phân tích rõ ràng và ngắn gọn về Affordances trong thiết kế UX, chúng tôi đã chia hướng dẫn này thành các phần sau:</p>



<ul class="wp-block-list">
<li>Affordances là gì?</li>



<li>Có những loại Affordances nào?</li>



<li>Affordances được sử dụng như thế nào trong thiết kế UX?</li>



<li>Làm thế nào để thiết kế các Affordances tốt nhất</li>
</ul>



<p><strong>Sẵn sàng để tìm hiểu về Affordances trong thiết kế UX? Bắt đầu nào.</strong></p>



<h2 class="wp-block-heading">Affordances là gì?</h2>



<p>Affordances là một chỉ số hấp dẫn về cách thức hoạt động của một mặt hàng và bao gồm cả chức năng nhận thức và thực tế của nó.</p>



<p>Chẳng hạn, khi bạn nhìn thấy một tay nắm cửa, bạn cho rằng chức năng của nó là để mở một cánh cửa. Khi bạn nhìn thấy một công tắc đèn, bạn cho rằng nó có thể được bật để bật đèn. Khi nhìn vào một chiếc ghế, bạn biết nó có thể ngồi được. Tất cả những thứ này đều có Affordances.</p>



<p><a href="https://en.wikipedia.org/wiki/Don_Norman" target="_blank" rel="noreferrer noopener">Don Norman</a> đề cập đến Affordances như các mối quan hệ trong cuốn sách <a href="https://www.amazon.com/Design-Everyday-Things-Revised-Expanded/dp/0465050654" target="_blank" rel="noreferrer noopener">Thiết kế của mọi thứ hàng ngày</a>. Anh ấy tiếp tục nói rằng, “khi Affordances được tận dụng, người dùng biết phải làm gì chỉ bằng cách nhìn: không cần hình ảnh, nhãn hiệu hay hướng dẫn.”</p>



<h2 class="wp-block-heading">Có những loại Affordances nào?</h2>



<p>Affordances được tìm thấy ở khắp mọi nơi, cả trong các sản phẩm vật lý và kỹ thuật số. Nhưng trước khi chúng ta tìm hiểu về Affordances dành riêng cho thiết kế UX, hãy xem qua 6 loại chính.</p>



<h3 class="wp-block-heading">1. Affordances rõ ràng</h3>



<p>Affordances rõ ràng là các đặc điểm nhận thức, rõ ràng của một mặt hàng giúp bạn biết được nó sẽ được sử dụng như thế nào.</p>



<p>Với Affordances rõ ràng, ngoại hình và bất kỳ ngôn ngữ hoặc văn bản đi kèm nào đều thông báo cho người dùng về cách sử dụng một đối tượng. Một ví dụ về Affordances rõ ràng là một nút có từ “Đăng nhập” trên đó. Giao diện (hình dạng, màu sắc, độ tương phản, v.v.) và văn bản đi kèm làm rõ rằng nút này được dùng để nhấn để đăng nhập.</p>



<figure class="wp-block-image size-full"><img loading="lazy" decoding="async" width="800" height="600" src="https://media.huynhhieutravel.com/daily_ui_001.gif" alt="" class="wp-image-9953"/></figure>



<h3 class="wp-block-heading">2. Affordances ẩn</h3>



<p>Affordances ẩn là các tính năng tiềm ẩn của một đối tượng. Các manh mối cho biết chức năng của một mục không rõ ràng và thậm chí có thể không được hiển thị cho đến khi hành động được thực hiện.</p>



<p>Một ví dụ phổ biến về Affordances ẩn là menu thả xuống hoặc tính năng có thể nhấp khác chỉ xuất hiện khi người dùng di chuột qua nó (Thường dùng trong các công cụ như Flip Box).</p>



<h3 class="wp-block-heading">3. Affordances mô hình</h3>



<p><strong>Affordances mô hình dựa trên các quy ước đã được thiết lập trước đó cho biết chức năng.&nbsp;</strong>Đây là những giao thức được sử dụng rộng rãi hoặc đã được thống nhất về cách thức hoạt động của mọi thứ.</p>



<p>Lấy một chiếc máy ảnh chẳng hạn.&nbsp;Nút chụp trên hầu hết nếu không phải tất cả các máy ảnh sẽ được tìm thấy ở trên cùng bên phải.&nbsp;Một ví dụ khác là văn bản được gạch chân, in nghiêng hoặc có màu khác biểu thị một liên kết trong phần nội dung văn bản.</p>



<figure class="wp-block-image size-full is-resized"><img loading="lazy" decoding="async" src="https://media.huynhhieutravel.com/Affordances-mo-hinh-wikipedia.jpg" alt="Affordances mô hình của Wikipedia" class="wp-image-9954" width="720" height="404" srcset="https://media.huynhhieutravel.com/Affordances-mo-hinh-wikipedia.jpg 960w, https://media.huynhhieutravel.com/Affordances-mo-hinh-wikipedia-768x431.jpg 768w" sizes="(max-width: 720px) 100vw, 720px" /><figcaption class="wp-element-caption">Affordances mô hình của Wikipedia</figcaption></figure>



<h3 class="wp-block-heading">4. Affordances ẩn dụ</h3>



<p>Affordances ẩn dụ dựa trên hình ảnh của các đối tượng thực hoặc nguyên bản để truyền đạt mục đích. Ví dụ: biểu tượng giỏ hàng để biểu thị giao dịch mua hàng trực tuyến của bạn, phong bì biểu thị email hoặc tin nhắn hoặc hình ảnh micrô hiển thị tùy chọn ghi âm.</p>



<p>Affordances ẩn dụ thường được tìm thấy trong các sản phẩm kỹ thuật số, nhưng có một số ứng dụng vật lý.</p>



<figure class="wp-block-image size-large is-resized"><img loading="lazy" decoding="async" src="https://media.huynhhieutravel.com/Affordances-an-du-trong-cac-icon-ung-dung-1024x720.jpg" alt="Affordances ẩn dụ trong các icon ứng dụng" class="wp-image-9955" width="768" height="540"/><figcaption class="wp-element-caption">Affordances ẩn dụ trong các icon ứng dụng</figcaption></figure>



<h3 class="wp-block-heading">5. Affordances sai</h3>



<p>Affordances sai xảy ra khi một tính năng của một mặt hàng gợi ý cách sử dụng mà mặt hàng đó thực sự không thể thực hiện được. Một ví dụ về điều này sẽ là một nút trông có vẻ nhấp được nhưng không phải, văn bản được gạch chân không chứa liên kết hoặc điều khiển TV bật đèn của bạn chứ không bật TV.</p>



<p><strong>Affordances sai thường xuất hiện do nhầm lẫn hoặc xảy ra do thiếu các kỹ thuật thiết kế hiệu quả.</strong></p>



<h3 class="wp-block-heading">6. Affordances tiêu cực</h3>



<p>Affordances tiêu cực được sử dụng khi truyền tải sự thiếu chức năng hoặc tính tương tác. Loại Affordances này thường được sử dụng khi bạn cần thêm thông tin từ người dùng và muốn chặn họ chuyển sang bước tiếp theo. Chẳng hạn, nút “Đăng nhập” màu xám không hoạt động cho đến khi người dùng của bạn nhập xong dữ liệu.</p>



<p><strong>Ví dụ Affordances tiêu cực dễ hình dung nhất dưới dạng button. </strong></p>



<figure class="wp-block-image size-full"><img loading="lazy" decoding="async" width="800" height="450" src="https://media.huynhhieutravel.com/nhung-button-Affordances-tieu-cuc.jpg" alt="Affordances button tiêu cực" class="wp-image-9956" srcset="https://media.huynhhieutravel.com/nhung-button-Affordances-tieu-cuc.jpg 800w, https://media.huynhhieutravel.com/nhung-button-Affordances-tieu-cuc-768x432.jpg 768w" sizes="(max-width: 800px) 100vw, 800px" /><figcaption class="wp-element-caption">Affordances button tiêu cực</figcaption></figure>



<h2 class="wp-block-heading" id="how-are-affordances-used-in-ux-design">Affordances được sử dụng như thế nào trong thiết kế UX?</h2>



<p>Bây giờ chúng ta đã đề cập đến các Affordances chính, chúng ta sẽ đi sâu hơn một chút về cách sử dụng Affordances trong thiết kế UX.</p>



<h3 class="wp-block-heading" id="buttons">Button</h3>



<p>Các button là một trong những yếu tố cốt lõi được sử dụng để đề xuất tính tương tác trong giao diện.&nbsp;Hình dạng, màu sắc, đổ bóng, độ tương phản và nội dung đi kèm đóng một vai trò rất lớn trong việc thiết kế một nút rõ ràng và hiệu quả.</p>



<p>Có thể dễ dàng vô tình tạo ra một Affordances ẩn bằng cách tạo một nút trông không thể nhấp được hoặc ngược lại, một Affordances sai bằng cách làm cho một mục khác trông có thể nhấp vào khi không.</p>



<h3 class="wp-block-heading" id="animations">Ảnh động</h3>



<p>Affordances hoạt hình thường bắt chước các hành động hoặc chuyển động trong thế giới thực (vuốt, đẩy, kéo, kéo, v.v.) và có phạm vi từ đơn giản đến khá phức tạp.&nbsp;Các nút chuyển đổi là các Affordances hoạt hình đơn giản hiển thị cho người dùng khi có thứ gì đó được bật bởi sự hiện diện hoặc thay đổi màu sắc khi kéo chuyển đổi.</p>



<p>Các hoạt ảnh phức tạp hơn có thể đóng vai trò là Affordances tiêu cực, chẳng hạn như nút bị rung, nhấp nháy hoặc khiến điện thoại của bạn rung cho biết bạn chưa thể tiếp tục.</p>



<h3 class="wp-block-heading" id="notifications">Thông báo</h3>



<p>Thông báo được sử dụng để thu hút sự chú ý của người dùng đến một cái gì đó hoặc để chỉ ra một sự thay đổi.</p>



<p>Ví dụ: giả sử người dùng chưa hoàn tất thiết lập hồ sơ của họ, một chấm đỏ có thể xuất hiện bên cạnh biểu tượng hồ sơ trên thanh menu.&nbsp;Một ví dụ điển hình khác là một số xuất hiện bên cạnh biểu tượng giỏ hàng khi bạn đã thêm thứ gì đó vào giỏ hàng của mình.&nbsp;Thông báo phải đủ rõ ràng để nhận thấy, nhưng không quá gây mất tập trung.</p>



<h3 class="wp-block-heading" id="input-fields">Trường đầu vào (Form)</h3>



<p>Các trường đầu vào chỉ ra rằng người dùng có thể nhập dữ liệu.&nbsp;Chúng thường được truyền đạt bởi hình dạng của trường và độ tương phản giữa trường và nền của nó.&nbsp;Hơn nữa, văn bản in nghiêng hoặc nhạt có thể xuất hiện để cho biết chính xác thông tin mà người dùng cần nhập.</p>



<p>Các trường nhập liệu cũng có thể xuất hiện dưới dạng hộp thả xuống cho biết người dùng cần thực hiện lựa chọn.</p>



<figure class="wp-block-image size-full"><img loading="lazy" decoding="async" width="800" height="450" src="https://media.huynhhieutravel.com/signup-form.jpg" alt="Sign up form" class="wp-image-9957" srcset="https://media.huynhhieutravel.com/signup-form.jpg 800w, https://media.huynhhieutravel.com/signup-form-768x432.jpg 768w" sizes="(max-width: 800px) 100vw, 800px" /><figcaption class="wp-element-caption">Sign up form</figcaption></figure>



<h3 class="wp-block-heading" id="iconsnbsp">Biểu tượng</h3>



<p>Các biểu tượng thường dựa vào Affordances mô hình hoặc Affordances ẩn dụ để giúp người dùng điều hướng qua một giao diện.&nbsp;Các quy ước như sử dụng biểu tượng trái tim hoặc ngôi sao để biểu thị trang “Yêu thích” sử dụng Affordances mẫu trong khi biểu tượng đĩa mềm làm nút “Lưu” dựa vào Affordances ẩn dụ.</p>



<p>Các biểu tượng cũng có thể được sử dụng để giúp người dùng hiểu phân loại vì người dùng có thể cảm nhận hình ảnh nhanh hơn văn bản.</p>



<h3 class="wp-block-heading" id="photos">Ảnh</h3>



<p>Tương tự như biểu tượng, ảnh là tín hiệu trực quan nhanh giúp người dùng hiểu những gì họ có thể làm với sản phẩm.</p>



<p>Ví dụ: trang web dành cho dịch vụ giao bữa ăn có thể có bản trình chiếu với hình ảnh mọi người đang nấu ăn hoặc các bữa ăn khác nhau mà họ cung cấp để cho người dùng biết sản phẩm của họ cung cấp những gì chỉ bằng một cái nhìn thoáng qua.</p>



<h2 class="wp-block-heading">Cách thiết kế với chi phí hợp lý nhất</h2>



<p>Thiết kế với chi phí hợp lý là nhằm giảm thiểu lỗi và va chạm của người dùng. Thiết kế của bạn không được gây hiểu lầm hoặc gây bất ngờ cho người dùng bằng cách dẫn đến thiếu hành động hoặc kết quả không mong muốn. Các yếu tố tương tác phải nổi bật và các chức năng quan trọng phải rõ ràng.</p>



<p>Dưới đây là một số điều cần ghi nhớ khi thiết kế Affordances tốt.</p>



<h3 class="wp-block-heading">Thực hiện theo các quy ước</h3>



<p>Người dùng đã mong đợi một số giao thức nhất định khi nói đến giao diện kỹ thuật số của họ.</p>



<p>Ví dụ: kính lúp hoặc “Tìm kiếm” trong thanh tìm kiếm hoặc biểu trưng thương hiệu có thể nhấp ở trên cùng bên trái của màn hình. Tuân theo các quy ước này sẽ giúp người dùng của bạn lướt qua sản phẩm của bạn.</p>



<h3 class="wp-block-heading">Bám sát các nguyên tắc thiết kế</h3>



<p>Các nguyên tắc thiết kế được thống nhất dựa trên các kỹ thuật giúp tạo ra các thiết kế trực quan và dễ sử dụng. Từ nhà thiết kế, nhà xã hội học đến nhà tâm lý học, nhiều chuyên gia đã đưa ra các nguyên tắc đơn giản mà bạn có thể tuân theo để giúp giảm thiểu sự nhầm lẫn cho người dùng của mình.</p>



<p><a href="https://lawsofux.com/" target="_blank" rel="noreferrer noopener">Laws of UX</a> cung cấp một bộ toàn diện các luật và nguyên tắc đã được thiết lập mà bạn có thể tuân theo; hoặc bạn có thể tạo ra các nguyên tắc phù hợp với công ty và sản phẩm của mình.</p>



<h2 class="wp-block-heading">Sử dụng bản sao hiệu quả</h2>



<p>Nếu bạn không thể tạo Affordances hiệu quả bằng cách sử dụng thiết kế trực quan do hạn chế về màu sắc, giới hạn phần mềm, ngân sách, v.v., thì việc kết hợp mọi thứ với văn bản hữu ích có thể giúp người dùng của bạn đi đúng hướng.</p>



<p>Chỉ cần đảm bảo giữ cho ngôn ngữ của bạn đơn giản và trực tiếp để người dùng có thể diễn giải dễ dàng.</p>



<p>Đôi khi việc tạo bản sao này thuộc về người viết UX, nhưng bất kể ai viết nó, có nhiều cách thiết thực để bạn có thể cải thiện kỹ năng viết UX của mình</p>



<h2 class="wp-block-heading">Làm quen với Thiết kế Vật liệu</h2>



<p><a href="https://m3.material.io/" target="_blank" rel="noreferrer noopener">Material Design</a> của Google là ngôn ngữ thiết kế theo định hướng của Android nhằm tối ưu hóa trải nghiệm cảm ứng trên màn hình của người dùng với các tính năng trực quan nhưng sáng tạo. Material Design sử dụng thế giới vật chất và đó là kết cấu, chuyển động có ý nghĩa và đồ họa có chủ ý để giúp bạn xây dựng giao diện chất lượng cao, thân thiện với người dùng.</p>



<h2 class="wp-block-heading">Hiểu người dùng của bạn</h2>



<p>Tiến hành nghiên cứu UX có ý nghĩa và tìm hiểu những gì người dùng của bạn muốn thấy khi tương tác trong bối cảnh sản phẩm của bạn. Mặc dù có một số điều mà hầu hết người dùng sẽ mong đợi với bất kỳ giao diện nào, nhưng có thể có những Affordances dự kiến ​​dành riêng cho người dùng của bạn và nhóm thuần tập mà họ đại diện.</p>
', 'Nhiều nhà thiết kế cố gắng tạo ra các sản phẩm dễ điều hướng đến mức người dùng của họ có thể lướt qua chúng ngay từ cái nhìn đầu tiên. Để thiết kế thứ gì đó với mức độ trực giác này, các nhà thiết kế bắt buộc phải hiểu Affordances—chúng là gì và [&hellip;]', 10065, 'post', '2023-07-23 10:34:27', '2023-07-24 13:33:29');
